INSERT INTO destinations
(name, slug, excerpt, intro, why_visit, things_to_do, best_time, how_to_get_there, suggested_itinerary, where_to_stay, travel_tips, faq_json, cta_title, cta_text, province, temperature, destination_type, recommended_stay, hero_image, cover_image, og_image, meta_title, meta_description, canonical_url, is_featured, sort_order, is_published)
VALUES
('Colombo','colombo','Gateway city for arrivals, food, markets, colonial streets, and first-night recovery before longer Sri Lanka routes.','Colombo works best as a practical first or last stop. Use it for arrival recovery, city food, Pettah market, Galle Face, Gangaramaya Temple, and a smooth transfer into the island.','The city answers high-intent searches around where to start a Sri Lanka itinerary and how to handle arrival day without losing time.','Galle Face Green, Pettah market, Gangaramaya Temple, Independence Square, Cinnamon Gardens, food walks, shopping, and sunset waterfront time.','Year-round. Keep outdoor walking for morning or late afternoon.','Bandaranaike International Airport to central Colombo usually takes 45 to 90 minutes depending on traffic.','Use Colombo for day 1 recovery or the final night before departure.','City hotels, boutique stays, airport hotels, and business-class properties are all practical.','Keep Colombo short unless travelers specifically want food, shopping, or city history.','[{"question":"How long should I spend in Colombo?","answer":"Most private tours need one night in Colombo or nearby Negombo, unless the traveler wants a deeper city food and culture day."}]','Plan Your Colombo Start','Use Colombo as a smart arrival or departure base for a private Sri Lanka route.','Western Province','27-31 C','City and Gateway','1-2 days',NULL,NULL,NULL,'Colombo Travel Guide for Sri Lanka Private Tours','Plan Colombo as a practical Sri Lanka arrival stop with food, markets, temples, waterfront time, and private onward transfers.',NULL,1,1,1),
('Kandy','kandy','Sacred hill-country city centered on the Temple of the Tooth, Kandy Lake, gardens, and cultural performance.','Kandy anchors the cultural hill-country route between Sigiriya, tea country, and Ella. It is especially useful for travelers seeking Buddhist heritage, cooler evenings, and scenic road or rail connections.','Kandy adds strong heritage value and makes a practical bridge between the Cultural Triangle and the highlands.','Temple of the Tooth, Kandy Lake, Royal Botanical Gardens, market streets, cultural dance, tea-country drives, and viewpoints.','December to April is generally comfortable; July and August are important for the Esala Perahera period.','Private road transfer from Sigiriya takes around 2.5 to 3.5 hours; from Colombo allow 3.5 to 4.5 hours.','Pair Kandy with Sigiriya before and Nuwara Eliya or Ella after.','Lake-view hotels, hill villas, heritage stays, and family-friendly properties.','Temple visits need modest clothing and flexible timing around ceremonies.','[{"question":"Is Kandy worth including in a first Sri Lanka trip?","answer":"Yes, especially when the route includes culture, Buddhism, gardens, and the hill-country connection."}]','Plan Your Kandy Visit','Add Kandy to a private culture and hill-country route.','Central Province','22-29 C','Culture and Heritage','1-2 days',NULL,NULL,NULL,'Kandy Travel Guide for Private Sri Lanka Tours','Visit Kandy with a private driver for the Temple of the Tooth, gardens, lake walks, cultural shows, and hill-country route planning.',NULL,1,2,1),
('Ella','ella','Highland scenery, the Nine Arch Bridge, tea estates, short hikes, waterfalls, and one of Sri Lanka''s most searched train routes.','Ella is a relaxed hill-country base with scenic viewpoints, tea landscapes, and easy soft-adventure experiences. It is one of the most searched Sri Lanka stops for first-time visitors.','Ella gives long-haul travelers a slower scenic break between heritage sites and the south coast or safari parks.','Nine Arch Bridge, Little Adam''s Peak, Ella Rock, Ravana Falls, tea walks, viewpoints, cafes, and the Kandy-Ella train section.','January to April and June to September are strong windows; mornings are usually best for viewpoints.','Kandy to Ella by train is scenic but slow. Private vehicle gives more control, while train segments can be added selectively.','Use Ella for two nights between Kandy/Nuwara Eliya and Yala or Udawalawe.','Guesthouses, boutique hill hotels, view lodges, and comfort stays around town.','Do not overpack one day. The roads and train are slow, and views are better with morning starts.','[{"question":"How many nights are enough for Ella?","answer":"Two nights works for most private itineraries, giving time for Nine Arch Bridge, Little Adam''s Peak, and a relaxed tea-country pace."}]','Plan Your Ella Route','Build Ella into a scenic private Sri Lanka itinerary.','Uva Province','18-26 C','Hill Country and Scenery','2-3 days',NULL,NULL,NULL,'Ella Sri Lanka Travel Guide and Private Route Ideas','Plan Ella with Nine Arch Bridge, tea country, viewpoints, waterfalls, and private transfers toward safari or the south coast.',NULL,1,3,1),
('Sigiriya','sigiriya','Sri Lanka''s iconic Lion Rock fortress with palace ruins, water gardens, frescoes, and nearby elephant safari country.','Sigiriya is the signature Cultural Triangle experience. The UNESCO-listed rock fortress rises above the plains and pairs naturally with Dambulla, Polonnaruwa, Minneriya, and Pidurangala.','It is one of the clearest entity pages for search: UNESCO heritage, fortress climb, ancient gardens, sunrise viewpoints, and elephant corridors all connect here.','Sigiriya Rock, Pidurangala sunrise, Dambulla Cave Temple, village lunch, Minneriya or Kaudulla safari, and Polonnaruwa day trip.','May to September is dry for the area; January to March is also popular for clear mornings.','From Colombo or the airport allow about 4 to 5 hours by private vehicle. From Kandy allow 2.5 to 3.5 hours.','Spend two nights in Sigiriya for rock climb, Dambulla, and one safari.','Jungle lodges, boutique eco hotels, family stays, and luxury wetland resorts.','Climb early, carry water, and keep a backup plan if rain or wasp warnings affect the rock.','[{"question":"Should I climb Sigiriya or Pidurangala?","answer":"Sigiriya is the archaeological site; Pidurangala is the sunrise viewpoint. Many travelers do both when they have two nights."}]','Plan Your Sigiriya Tour','Include Sigiriya in a private Cultural Triangle route.','Central / North Central Province','25-32 C','UNESCO Heritage','1-2 days',NULL,NULL,NULL,'Sigiriya Travel Guide for Sri Lanka Private Tours','Plan Sigiriya, Pidurangala, Dambulla, and elephant safaris with private transport and practical timings.',NULL,1,4,1),
('Yala','yala','Sri Lanka''s best-known safari region for leopard-focused wildlife drives, elephants, birds, and southern route combinations.','Yala is the high-demand wildlife stop on many Sri Lanka itineraries. It works well after Ella or before the south coast, especially for travelers searching for leopard safari experiences.','The destination satisfies wildlife, photography, family, and luxury camp intent in one route node.','Morning safari, afternoon safari, Bundala birding extension, Sithulpawwa, Kataragama, beach rest in Tangalle, and Yala buffer-zone lodges.','February to July is often strong for visibility; park access and block openings can vary.','From Ella allow around 2.5 to 3.5 hours. From Galle or Tangalle allow 2 to 4 hours depending on base.','Use one or two nights, with one early safari and enough rest after the drive.','Safari lodges, tented camps, family lodges, and luxury wilderness stays.','Leopard sightings are never guaranteed. Book ethical operators and avoid crowding animals.','[{"question":"Is Yala better than Udawalawe?","answer":"Yala is stronger for leopard search and varied habitats; Udawalawe is more consistent for elephants and easier for families."}]','Plan Your Yala Safari','Add a well-timed Yala safari to your private route.','Southern / Uva Province','27-34 C','Wildlife Safari','1-2 days',NULL,NULL,NULL,'Yala National Park Safari Guide for Sri Lanka Tours','Plan Yala leopard safaris with private transfers, route timing, lodge choices, and realistic wildlife expectations.',NULL,1,5,1),
('Galle','galle','UNESCO-listed fort city with Dutch-era walls, lighthouse views, boutique stays, cafes, shops, and south-coast access.','Galle Fort is the most polished heritage stop on the south coast. It pairs well with beaches, whale watching, surf towns, and Colombo airport departures.','Galle works for culture, architecture, food, shopping, luxury boutique stays, and family-friendly walking routes.','Fort walls, lighthouse, Dutch Reformed Church, maritime museum area, cafes, galleries, sunset walks, Unawatuna, and coastal drives.','November to April is the best south-coast beach season; Galle Fort itself works year-round.','From Colombo allow 2 to 3 hours by expressway. From Mirissa allow about 1 hour.','Use Galle for one or two nights near the end of a southern route.','Boutique fort hotels, villas, family hotels, and beach stays nearby.','Book restaurants during peak season and keep fort walks for sunset or morning.','[{"question":"Can Galle be a day trip from Colombo?","answer":"Yes, but one night is better if the traveler wants fort walks, dining, and nearby beaches without rushing."}]','Plan Your Galle Stop','Add Galle Fort to a private south-coast itinerary.','Southern Province','26-31 C','UNESCO Heritage Coast','1-2 days',NULL,NULL,NULL,'Galle Fort Travel Guide for Sri Lanka Private Tours','Visit Galle Fort with private south-coast transfers, lighthouse walks, boutique stays, beaches, and heritage route planning.',NULL,1,6,1),
('Nuwara Eliya','nuwara-eliya','Cool tea-country town with estates, colonial character, gardens, waterfalls, and Horton Plains access.','Nuwara Eliya gives Sri Lanka itineraries a highland change of climate and scenery. It is a natural stop between Kandy and Ella.','The destination answers tea country, train, cooler weather, colonial bungalow, and Horton Plains search intent.','Tea factory visits, Gregory Lake, Victoria Park, scenic viewpoints, waterfalls, market walks, and Horton Plains day trip.','January to April is popular; April is busy locally. Mornings are best for viewpoints and Horton Plains.','From Kandy allow around 2.5 to 3.5 hours by private vehicle. Train segments can be added from Nanu Oya.','Use one night for tea country or two nights when adding Horton Plains.','Tea estate bungalows, colonial hotels, town hotels, and view lodges.','Carry warm layers. The climate is much cooler than the coast.','[{"question":"Is Nuwara Eliya different from Ella?","answer":"Yes. Nuwara Eliya is cooler and tea-estate focused; Ella is more relaxed, hike-oriented, and social."}]','Plan Your Tea Country Stay','Add Nuwara Eliya to a private highland route.','Central Province','12-22 C','Tea Country','1-2 days',NULL,NULL,NULL,'Nuwara Eliya Travel Guide for Tea Country Tours','Plan Nuwara Eliya tea estates, cool highland stays, Horton Plains access, and private transfers through Sri Lanka hill country.',NULL,0,7,1),
('Mirissa','mirissa','South-coast beach base known for whale watching, relaxed dining, sunset viewpoints, and easy Galle or Weligama access.','Mirissa is a compact beach stop for travelers who want ocean time without losing access to Galle, Weligama, and Matara.','It captures whale watching, beach, couples, surf-nearby, and relaxed south-coast intent.','Whale watching in season, beach time, Coconut Tree Hill, Parrot Rock, seafood dinners, Weligama surf, and day trips to Galle.','November to April is the main south-coast season and whale watching window.','From Galle allow about 1 hour. From Yala or Udawalawe allow 3 to 4.5 hours depending on route.','Use Mirissa for one or two nights after wildlife or heritage stops.','Beach guesthouses, small hotels, villas, and boutique coastal stays.','Choose responsible whale-watching boats and expect early starts.','[{"question":"When is whale watching best in Mirissa?","answer":"The main season is usually November to April, when south-coast seas are calmer."}]','Plan Your Mirissa Beach Stay','Add Mirissa to a relaxed south-coast private route.','Southern Province','27-31 C','Beach and Marine Wildlife','1-2 days',NULL,NULL,NULL,'Mirissa Sri Lanka Travel Guide for Beach and Whale Watching','Plan Mirissa whale watching, beach time, Weligama surf links, and private south-coast transfers.',NULL,0,8,1),
('Udawalawe','udawalawe','Accessible safari destination with reliable elephant sightings, open landscapes, and family-friendly wildlife pacing.','Udawalawe is one of the easiest safari choices for private routes, especially for families and first-time safari travelers.','It is a practical wildlife page for elephant search intent and works well between Ella and the south coast.','Jeep safari, Elephant Transit Home, reservoir views, birdlife, village stays, and route links to Ella, Tangalle, or Galle.','Generally year-round, with dry months often improving wildlife visibility.','From Ella allow about 2.5 to 3 hours. From Galle or Tangalle allow 2.5 to 4 hours.','Use one night or a long transfer day with afternoon safari.','Safari lodges, family lodges, and simple guesthouses near the park.','Book safari times around animal activity, not just transfer convenience.','[{"question":"Is Udawalawe good for children?","answer":"Yes. It is one of Sri Lanka''s most practical safari choices for families because elephant sightings are relatively consistent."}]','Plan Your Udawalawe Safari','Include Udawalawe in a family-friendly private wildlife route.','Sabaragamuwa Province','27-33 C','Wildlife Safari','1-2 days',NULL,NULL,NULL,'Udawalawe Safari Guide for Private Sri Lanka Tours','Plan Udawalawe elephant safaris, family routes, Elephant Transit Home visits, and private road transfers.',NULL,0,9,1),
('Trincomalee','trincomalee','East-coast beach and harbor region with Nilaveli, Pigeon Island, Hindu temples, diving, and calm seas in mid-year.','Trincomalee is a strong east-coast option when the south-west monsoon affects the southern beaches. It pairs with Sigiriya, Polonnaruwa, and Passikudah.','It gives the site seasonal coverage for May to September beach searches and adds culture through Koneswaram Temple.','Nilaveli, Uppuveli, Pigeon Island snorkeling, Koneswaram Temple, Fort Frederick, whale watching in season, diving, and coastal rest.','May to September is usually the stronger east-coast beach window.','From Sigiriya or Dambulla allow about 2.5 to 3.5 hours by private vehicle.','Use two or three nights after the Cultural Triangle in mid-year itineraries.','Beach hotels, dive lodges, family resorts, and simple guesthouses.','Check sea conditions for snorkeling and protect coral by choosing responsible operators.','[{"question":"When is Trincomalee best?","answer":"Trincomalee is usually best from May to September, when the east coast often has calmer beach conditions."}]','Plan Your Trincomalee Stay','Use Trincomalee for a seasonal east-coast beach route.','Eastern Province','27-33 C','East Coast Beach','2-3 days',NULL,NULL,NULL,'Trincomalee Travel Guide for East Coast Sri Lanka Tours','Plan Trincomalee, Nilaveli, Pigeon Island, Koneswaram Temple, and private east-coast travel from the Cultural Triangle.',NULL,0,10,1),
('Anuradhapura','anuradhapura','Ancient royal capital with sacred stupas, the Sri Maha Bodhi, reservoirs, monasteries, and deep Buddhist heritage.','Anuradhapura is one of Sri Lanka''s major ancient capitals and a key Buddhist pilgrimage destination. It suits travelers who want a deeper Cultural Triangle route.','The page supports UNESCO heritage, Buddhism, pilgrimage, archaeology, and culture-rich itinerary intent.','Sri Maha Bodhi, Ruwanwelisaya, Jetavanaramaya, Abhayagiri, Isurumuniya, ancient reservoirs, Mihintale, and cycling routes.','January to September is generally practical; start early because sites are exposed.','From Sigiriya allow around 1.5 to 2.5 hours. From Colombo allow 4 to 5 hours.','Use one night when the route has strong heritage focus, or visit from Sigiriya.','Heritage hotels, city hotels, pilgrimage stays, and boutique properties.','Wear respectful clothing and allow enough time between large sacred sites.','[{"question":"Is Anuradhapura worth visiting if I see Sigiriya?","answer":"Yes, if the traveler wants ancient Buddhist heritage and sacred sites. Sigiriya and Anuradhapura are different experiences."}]','Plan Your Anuradhapura Route','Add Anuradhapura to a deeper Cultural Triangle itinerary.','North Central Province','25-33 C','Ancient Heritage','1-2 days',NULL,NULL,NULL,'Anuradhapura Travel Guide for Cultural Triangle Tours','Plan Anuradhapura ancient city visits, sacred Buddhist sites, Mihintale, and private Cultural Triangle transfers.',NULL,0,11,1),
('Polonnaruwa','polonnaruwa','Compact medieval capital with ruins, stone Buddha images, cycling routes, reservoirs, and strong Sigiriya connections.','Polonnaruwa is one of the easiest ancient cities to include from Sigiriya. Its ruins are spread enough for cycling but compact enough for a focused day.','It captures UNESCO, ancient city, cycling, family, and archaeology intent with better pacing than a rushed multi-city day.','Royal Palace area, Gal Vihara, Quadrangle, Parakrama Samudra, museum, cycling routes, and Minneriya extension.','May to September is practical for the region; mornings are best.','From Sigiriya allow about 1.5 hours. From Trincomalee allow around 2.5 to 3 hours.','Visit as a day trip from Sigiriya or overnight on a deeper heritage route.','Simple city hotels, heritage-region lodges, and Sigiriya-based stays.','Use bikes only if heat and fitness suit the group. A private vehicle keeps families comfortable.','[{"question":"Can Polonnaruwa be done as a day trip?","answer":"Yes. Many private tours visit Polonnaruwa from Sigiriya with a morning start."}]','Plan Your Polonnaruwa Visit','Include Polonnaruwa in a Cultural Triangle route.','North Central Province','25-33 C','Ancient Heritage','Day trip or 1 night',NULL,NULL,NULL,'Polonnaruwa Travel Guide for Sri Lanka Heritage Tours','Plan Polonnaruwa ruins, Gal Vihara, cycling options, and private transfers from Sigiriya or Trincomalee.',NULL,0,12,1),
('Arugam Bay','arugam-bay','East-coast surf town with seasonal waves, relaxed beach energy, lagoons, wildlife edges, and long-stay appeal.','Arugam Bay is Sri Lanka''s best-known surf base and a strong choice for adventurous travelers in the east-coast season.','It expands the site beyond classic circuits into surf, youth, long-stay, and active travel demand.','Main Point surf, Peanut Farm, lagoon safari, Kumana National Park, beach cafes, yoga, and relaxed coastal evenings.','May to September is the main surf and east-coast season.','From Ella allow around 3 to 4 hours. From Yala/Tissamaharama allow 3 to 4 hours depending on route.','Use two or three nights when surf or slow beach time matters.','Surf guesthouses, beach cabanas, boutique stays, and casual hotels.','Road transfers are long, so avoid adding Arugam Bay to a very short itinerary.','[{"question":"Is Arugam Bay only for surfers?","answer":"No, but it is strongest for surf, relaxed beach culture, yoga, and east-coast slow travel."}]','Plan Your Arugam Bay Trip','Add surf and east-coast beach time to your Sri Lanka route.','Eastern Province','27-33 C','Surf and Beach','2-4 days',NULL,NULL,NULL,'Arugam Bay Travel Guide for Surf and East Coast Tours','Plan Arugam Bay surf, beaches, Kumana, lagoon safaris, and private transfers from Ella or Yala.',NULL,0,13,1),
('Bentota','bentota','West-south coast resort area with beaches, river trips, water sports, villas, and easy airport or Galle access.','Bentota is a convenient beach stop for travelers who want resort comfort without driving deep into the south coast.','It supports luxury, family, water-sports, short-break, and airport-friendly beach intent.','Bentota Beach, Bentota River safari, water sports, Brief Garden, turtle conservation visits, and coastal villas.','November to April is the stronger west and south coast beach window.','From Colombo or the airport allow about 1.5 to 2.5 hours by expressway and coastal road.','Use Bentota for two nights after a cultural route or before departure.','Beach resorts, villas, family hotels, and luxury properties.','Choose Bentota when transfer convenience matters more than remote beach character.','[{"question":"Is Bentota good for families?","answer":"Yes. Bentota works well for families who want resort facilities, beach time, and shorter transfers."}]','Plan Your Bentota Beach Stay','Use Bentota for a comfortable beach finish.','Southern / Western Coast','26-31 C','Beach Resort','2-3 days',NULL,NULL,NULL,'Bentota Travel Guide for Sri Lanka Beach Tours','Plan Bentota beach resorts, river safaris, family water sports, and private transfers from Colombo or Galle.',NULL,0,14,1),
('Hikkaduwa','hikkaduwa','Lively south-west beach town known for reef, turtles, snorkeling, surf, cafes, and easy Galle access.','Hikkaduwa suits travelers who want a more active beach town with snorkeling, surf lessons, nightlife, and simple Galle day trips.','It supports beach, surf, snorkeling, turtle, budget, and social travel intent.','Hikkaduwa Beach, reef snorkeling, surf lessons, turtle viewing areas, Seenigama, cafes, and Galle day trip.','November to April is usually best for sea conditions on this coast.','From Galle allow about 30 to 45 minutes. From Colombo allow around 2 to 3 hours.','Use one or two nights for active beach time near Galle.','Beach hotels, guesthouses, apartments, and mid-range resorts.','Choose reef-safe sunscreen and avoid touching or feeding turtles.','[{"question":"Is Hikkaduwa better than Mirissa?","answer":"Hikkaduwa is livelier and closer to Galle; Mirissa is smaller and stronger for whale watching."}]','Plan Your Hikkaduwa Stop','Add Hikkaduwa to a lively south-west beach route.','Southern Province','26-31 C','Beach and Reef','1-3 days',NULL,NULL,NULL,'Hikkaduwa Travel Guide for Beach, Surf, and Snorkeling','Plan Hikkaduwa beaches, reef snorkeling, surf lessons, turtle viewing, and private transfers near Galle.',NULL,0,15,1),
('Jaffna','jaffna','Northern cultural city with Tamil heritage, temples, islands, colonial traces, food, and a very different Sri Lanka rhythm.','Jaffna is ideal for return visitors and travelers who want a deeper northern route. It adds Tamil culture, temple architecture, island drives, and distinctive food.','It helps the site answer high-value exploratory searches beyond the classic first-time circuit.','Nallur Kandaswamy Temple, Jaffna Fort, Delft Island, Casuarina Beach, local food, markets, and causeway drives.','January to September is generally practical; it can be hot, so plan early starts.','From Anuradhapura allow around 3 to 4 hours. From Colombo it is a long road or rail journey.','Use two nights when adding the north to a longer itinerary.','City hotels, boutique guesthouses, and simple local stays.','Respect temple dress codes and avoid making the northern route too rushed.','[{"question":"Should first-time visitors include Jaffna?","answer":"Only on longer itineraries. Jaffna is rewarding, but it adds distance and works best for travelers seeking deeper culture."}]','Plan Your Jaffna Extension','Add northern Sri Lanka to a longer private itinerary.','Northern Province','27-34 C','Northern Culture','2-3 days',NULL,NULL,NULL,'Jaffna Travel Guide for Northern Sri Lanka Tours','Plan Jaffna temples, islands, food, forts, and private northern Sri Lanka extensions.',NULL,0,16,1),
('Negombo','negombo','Airport-friendly coastal town with lagoon, fishing culture, beach hotels, and easy first-night or last-night logistics.','Negombo is often the most practical first or last stop because it sits close to Bandaranaike International Airport.','It answers airport transfer, arrival night, beach near airport, and family logistics intent.','Negombo Lagoon, fish market, Dutch canal, churches, beach hotels, seafood dinners, and airport pickup.','Year-round as a logistics stop; November to April is stronger for west-coast beach weather.','Airport to Negombo usually takes 20 to 40 minutes.','Use Negombo for arrival recovery or the final night before a morning flight.','Airport hotels, beach hotels, boutique villas, and family stays.','Choose Negombo over Colombo when flight timing and beach recovery matter more than city sightseeing.','[{"question":"Is Negombo better than Colombo for arrival night?","answer":"Negombo is usually easier for flight recovery because it is closer to the airport and has beach hotels."}]','Plan Your Airport Night','Use Negombo for easy arrival and departure logistics.','Western Province','26-31 C','Airport Beach Base','1 night',NULL,NULL,NULL,'Negombo Travel Guide for Sri Lanka Arrival and Departure','Plan Negombo airport hotels, beach recovery, lagoon visits, and private airport transfers.',NULL,0,17,1),
('Dambulla','dambulla','Cave temple gateway for Sigiriya, Matale, Kandy, and the Cultural Triangle, with efficient road connections.','Dambulla is both a UNESCO cave-temple stop and a road hub for central Sri Lanka. It is often visited with Sigiriya.','It supports cave temple, Buddhist heritage, Cultural Triangle, and route-planning intent.','Dambulla Cave Temple, Golden Temple area, produce market, Sigiriya connection, Matale spice stops, and Minneriya access.','May to September and January to March are practical for the region; temple visits are best in morning.','From Sigiriya allow 30 to 45 minutes. From Kandy allow around 2 to 3 hours.','Use Dambulla as a half-day stop or stay nearby when Sigiriya hotels suit the route.','Most travelers stay in Sigiriya, Habarana, or Dambulla hotels depending on pacing.','Cover shoulders and knees for temple visits.','[{"question":"Can Dambulla and Sigiriya be visited on the same day?","answer":"Yes, but a two-night Cultural Triangle base gives better pacing for the rock, cave temple, and safari."}]','Plan Your Dambulla Visit','Connect Dambulla with Sigiriya and Kandy on a private route.','Central Province','25-32 C','Cave Temple and Route Hub','Half day',NULL,NULL,NULL,'Dambulla Cave Temple Travel Guide for Sri Lanka Tours','Plan Dambulla Cave Temple, Sigiriya links, Cultural Triangle transfers, and private route timing.',NULL,0,18,1),
('Horton Plains','horton-plains','Highland national park known for World''s End, Baker''s Falls, grasslands, cloud forest, and early-morning hiking.','Horton Plains is a highland nature experience usually accessed from Nuwara Eliya. It requires an early start for the best visibility.','It adds nature, hiking, cloud forest, and Central Highlands UNESCO intent.','World''s End viewpoint, Baker''s Falls, cloud forest, grasslands, sambar deer, and photography.','January to March is often clearest, but early morning matters in every season.','From Nuwara Eliya allow around 1 to 1.5 hours to the entrance area, plus hiking time.','Add as an early morning day trip from Nuwara Eliya.','Stay in Nuwara Eliya or nearby highland properties.','Leave early, bring layers, and expect mist after late morning.','[{"question":"How hard is Horton Plains?","answer":"The main loop is moderate for active travelers, but it needs an early start and cool-weather preparation."}]','Plan Your Horton Plains Hike','Add Horton Plains to a highland private route.','Central Province','8-18 C','Highland Nature','Half day',NULL,NULL,NULL,'Horton Plains Travel Guide for Sri Lanka Highland Tours','Plan Horton Plains, World''s End, Baker''s Falls, and private early-morning transfers from Nuwara Eliya.',NULL,0,19,1),
('Knuckles Mountain Range','knuckles-mountain-range','Rugged mountain region for guided trekking, cloud forest, village routes, waterfalls, and serious nature travel.','Knuckles is best for active travelers who want guided hiking away from the classic tourist trail.','It supports hiking, adventure, nature, responsible travel, and high-value bespoke itinerary intent.','Guided treks, village trails, waterfalls, viewpoints, birdlife, cloud forest, and overnight nature stays.','January to March and June to September can be practical, but local trail conditions matter.','Access varies by trailhead; from Kandy allow around 1.5 to 3 hours depending on route.','Use one or two nights for a guided trekking extension.','Eco lodges, simple village stays, and nature properties around trailheads.','Use licensed guides and keep expectations flexible in rain or mist.','[{"question":"Can I visit Knuckles without a guide?","answer":"A guide is strongly recommended because trails, weather, and access points vary."}]','Plan a Knuckles Trek','Add guided trekking to a private Sri Lanka itinerary.','Central Province','16-26 C','Mountain Trekking','1-2 days',NULL,NULL,NULL,'Knuckles Mountain Range Travel Guide for Guided Treks','Plan guided Knuckles treks, waterfalls, villages, cloud forest, and private transfers from Kandy.',NULL,0,20,1),
('Unawatuna','unawatuna','Beach village near Galle with swimming, cafes, family-friendly coves, Japanese Peace Pagoda, and easy fort access.','Unawatuna is a practical beach base close to Galle Fort, making it useful for travelers who want beach time and heritage in one stop.','It supports family beach, Galle beach base, snorkeling, and south-coast short-stay intent.','Unawatuna Beach, Jungle Beach, Japanese Peace Pagoda, snorkeling, cafes, Galle Fort, and coastal viewpoints.','November to April is the main south-coast season.','From Galle Fort allow about 15 to 25 minutes by private vehicle.','Use one or two nights near Galle or as a family beach stop.','Beach hotels, villas, guesthouses, and family-friendly stays.','Choose accommodation carefully because some roads are narrow and beach access varies.','[{"question":"Is Unawatuna good with Galle?","answer":"Yes. Unawatuna is one of the easiest beach bases for visiting Galle Fort."}]','Plan Your Unawatuna Stay','Pair Unawatuna beach time with Galle Fort.','Southern Province','26-31 C','Beach Near Galle','1-2 days',NULL,NULL,NULL,'Unawatuna Travel Guide for Beach Stays near Galle','Plan Unawatuna, Jungle Beach, Japanese Peace Pagoda, Galle Fort, and private south-coast transfers.',NULL,0,21,1),
('Weligama','weligama','Beginner-friendly surf bay with easy lessons, cafes, villas, and quick access to Mirissa, Ahangama, and Galle.','Weligama is a strong surf-learning base and a flexible south-coast stop for couples, families, and younger travelers.','It supports surf lesson, south coast, long stay, and flexible beach itinerary intent.','Beginner surf lessons, bay beach, seafood, Ahangama cafes, Mirissa day trip, and Galle extension.','November to April is the main south-coast season; surf lessons run across many months depending on conditions.','From Galle allow about 45 to 60 minutes. From Mirissa allow 20 to 30 minutes.','Use two nights for surf learning or as a base between Galle and Mirissa.','Surf hotels, villas, guesthouses, and boutique stays.','Pick instructors carefully and avoid overloaded beaches at peak lesson times.','[{"question":"Is Weligama good for beginner surfers?","answer":"Yes. Weligama Bay is one of Sri Lanka''s most practical beginner surf areas."}]','Plan Your Weligama Surf Stop','Add beginner surf time to a private south-coast route.','Southern Province','26-31 C','Surf Beach','2-3 days',NULL,NULL,NULL,'Weligama Travel Guide for Surf and South Coast Tours','Plan Weligama surf lessons, villas, Ahangama, Mirissa, Galle, and private coastal transfers.',NULL,0,22,1),
('Tangalle','tangalle','Quieter south-coast beach area with wide sands, turtle beaches, lagoon nature, and luxury hideaways.','Tangalle suits travelers who want a quieter beach finish after Yala, Udawalawe, or Ella.','It supports luxury beach, quiet honeymoon, family villa, and turtle beach intent.','Tangalle Beach, Rekawa turtle area, Mulkirigala, lagoons, villas, and slow beach days.','November to April is usually best for this coast.','From Yala allow around 2 to 3 hours. From Galle allow 2 to 3 hours.','Use two or three nights for a slower beach ending.','Boutique beach hotels, villas, and luxury coastal properties.','Swimming conditions vary by beach, so choose hotels according to traveler needs.','[{"question":"Is Tangalle quieter than Mirissa?","answer":"Yes. Tangalle is generally quieter and more spread out, while Mirissa is livelier and more compact."}]','Plan Your Tangalle Beach End','Finish a private route with a quieter south-coast stay.','Southern Province','26-31 C','Quiet Beach','2-3 days',NULL,NULL,NULL,'Tangalle Travel Guide for Quiet South Coast Beach Tours','Plan Tangalle beaches, Rekawa, Mulkirigala, luxury villas, and private transfers from Yala or Galle.',NULL,0,23,1),
('Adams Peak','adams-peak','Pilgrimage mountain near Hatton known for sunrise climbs, tea-country views, and seasonal night ascents.','Adam''s Peak is a meaningful climb for pilgrims and active travelers. It is best handled as a focused overnight plan, not an add-on after a long transfer.','It supports pilgrimage, sunrise hike, active travel, and hill-country special-interest intent.','Night climb, sunrise viewpoint, tea-country scenery, Hatton base, Nallathanniya, and nearby waterfalls.','The main pilgrimage season usually runs around December to May. Weather and access vary.','Hatton or Nallathanniya are the usual bases; road timing depends heavily on the previous stop.','Use one night near the trailhead with a light day before the climb.','Simple guesthouses and hill-country stays around the trailhead or Hatton.','Prepare for many steps, changing weather, and crowded pilgrimage nights.','[{"question":"Can Adam''s Peak fit into a short Sri Lanka itinerary?","answer":"Only if the traveler is specifically interested in the climb. It needs careful timing and rest."}]','Plan Your Adam''s Peak Climb','Add Adam''s Peak as a focused active extension.','Central / Sabaragamuwa Province','10-24 C','Pilgrimage and Hiking','1 night',NULL,NULL,NULL,'Adam''s Peak Travel Guide for Sri Lanka Pilgrimage and Hiking','Plan Adam''s Peak sunrise climbs, Hatton transfers, pilgrimage timing, and private hill-country route support.',NULL,0,24,1),
('Kurunegala','kurunegala','Practical inland stop with rock viewpoints, temples, reservoirs, and useful routing between Colombo, Kandy, and Anuradhapura.','Kurunegala is not a classic tourist base, but it can serve practical route planning and offbeat cultural stops.','It adds long-tail geographic coverage and supports custom-driver route planning searches.','Ethagala viewpoint, temples, reservoirs, local markets, road-break stops, and regional culture.','Year-round as a route stop; keep viewpoints for morning or late afternoon.','It sits between Colombo, Kandy, Anuradhapura, and the Cultural Triangle road network.','Use as a road-break or special-interest stop, not a default overnight.','City hotels and simple local stays.','Use only when it improves the route or matches traveler interest.','[{"question":"Is Kurunegala a main tourist destination?","answer":"No. It is best used as a practical or offbeat stop inside custom private routes."}]','Ask About Kurunegala Routes','Use Kurunegala only when it fits the route.','North Western Province','25-32 C','Offbeat Route Stop','Half day',NULL,NULL,NULL,'Kurunegala Travel Guide for Custom Sri Lanka Routes','Plan Kurunegala as an offbeat stop or route break between Colombo, Kandy, and the Cultural Triangle.',NULL,0,25,1),
('Mannar','mannar','Remote north-west coastal region with causeways, birdlife, baobab trees, Adam''s Bridge stories, and slow-travel appeal.','Mannar is best for travelers who want remote landscapes, birding, history, and a different side of Sri Lanka.','It gives the site long-tail coverage for birding, northern coast, and special-interest private tours.','Mannar Island, Talaimannar, birding areas, baobab tree, causeways, churches, and coastal viewpoints.','December to March is often stronger for birding and dry weather.','From Anuradhapura or Jaffna allow long private road transfers.','Use one or two nights on a northern or birding-focused itinerary.','Simple local hotels and guesthouses.','Expect fewer luxury options and plan meals and stops carefully.','[{"question":"Who should visit Mannar?","answer":"Mannar suits birders, photographers, repeat visitors, and travelers who enjoy remote coastal landscapes."}]','Plan a Mannar Extension','Add Mannar to a northern or birding route.','Northern Province','27-34 C','Remote Coast and Birding','1-2 days',NULL,NULL,NULL,'Mannar Travel Guide for Northern Coast and Birding Tours','Plan Mannar Island, birding, Talaimannar, remote coast routes, and private northern Sri Lanka transfers.',NULL,0,26,1),
('Passikudah','passikudah','East-coast bay known for shallow water, family resorts, calm seasonal seas, and easy pairing with Batticaloa.','Passikudah is a family-friendly east-coast beach option with resort comfort and calmer seasonal water.','It supports family beach, east coast, resort, and May-September seasonal itinerary intent.','Passikudah Bay, beach resorts, shallow swimming, Batticaloa day trip, and coastal rest after culture.','May to September is usually the stronger east-coast window.','From Polonnaruwa allow around 2.5 to 3.5 hours. From Trincomalee allow 2.5 to 3.5 hours.','Use two or three nights after the Cultural Triangle in mid-year routes.','Beach resorts, family hotels, and coastal villas.','Best for travelers who value calm resort beach time over nightlife.','[{"question":"Is Passikudah good for families?","answer":"Yes. The bay is known for shallow water and resort-style stays, especially in the east-coast season."}]','Plan Your Passikudah Beach Stay','Add calm east-coast beach time to your route.','Eastern Province','27-33 C','East Coast Beach Resort','2-3 days',NULL,NULL,NULL,'Passikudah Travel Guide for East Coast Sri Lanka Beach Tours','Plan Passikudah resorts, family beach stays, Batticaloa links, and private transfers from the Cultural Triangle.',NULL,0,27,1),
('Batticaloa','batticaloa','Eastern lagoon city with colonial traces, local culture, beaches nearby, and links to Passikudah and Kallady.','Batticaloa is useful for travelers exploring the east coast beyond resort beaches.','It supports east-coast culture, lagoon, local city, and regional route intent.','Batticaloa Fort, Kallady Bridge, lagoon views, local food, nearby beaches, and Passikudah extension.','May to September is generally stronger for east-coast beach conditions.','From Passikudah allow around 45 to 60 minutes. From Polonnaruwa allow about 3 hours.','Use as a day stop or one-night east-coast city break.','City hotels and coastal stays nearby.','Keep expectations local and low-key compared with resort towns.','[{"question":"Should I stay in Batticaloa or Passikudah?","answer":"Most leisure travelers stay in Passikudah and visit Batticaloa as a cultural stop."}]','Plan an East Coast Route','Connect Batticaloa with Passikudah and Trincomalee.','Eastern Province','27-33 C','East Coast Culture','Day stop or 1 night',NULL,NULL,NULL,'Batticaloa Travel Guide for East Coast Sri Lanka Routes','Plan Batticaloa lagoon, fort, Kallady, Passikudah links, and private east-coast transfers.',NULL,0,28,1),
('Matara','matara','Southern city with fort traces, beaches, Dondra Head, temples, and route links between Mirissa, Weligama, and Tangalle.','Matara is a practical south-coast stop rather than a default overnight for most private tours.','It supports southern coast geographic coverage and helps interlink Mirissa, Weligama, Tangalle, and Dondra.','Dondra Head lighthouse, Matara Fort area, Weherahena Temple, Polhena Beach, coastal drives, and local markets.','November to April is the main south-coast beach season.','From Mirissa or Weligama allow 20 to 45 minutes; from Tangalle allow about 1 hour.','Use as a day stop between south-coast bases.','Most travelers stay in Mirissa, Weligama, Tangalle, or nearby villas.','Use Matara for specific sights or transfer breaks, not as a rushed checklist item.','[{"question":"Is Matara worth a stop?","answer":"Yes, when Dondra Head, temples, local markets, or coastal routing fit the traveler."}]','Plan a Matara Stop','Use Matara as a focused south-coast waypoint.','Southern Province','26-31 C','Southern Coast City','Half day',NULL,NULL,NULL,'Matara Travel Guide for South Coast Sri Lanka Tours','Plan Matara, Dondra Head, Polhena, temples, and private transfers between Mirissa and Tangalle.',NULL,0,29,1),
('Ratnapura','ratnapura','Gem-city region with rainforest access, waterfalls, pilgrimage routes, and links toward Adam''s Peak or Sinharaja.','Ratnapura is a special-interest inland destination for gems, rainforest, waterfalls, and pilgrimage-linked travel.','It supports gem, rainforest, waterfall, and offbeat custom-tour intent.','Gem museums and markets, waterfalls, Sinharaja access routes, Adam''s Peak approaches, and local culture.','January to March and June to September can work, but rainfall patterns matter.','From Colombo allow around 2.5 to 4 hours depending on traffic and route.','Use as a specialist stop on nature, gem, or pilgrimage routes.','Simple hotels, eco stays, and rainforest-area properties.','Check rainforest access and weather before committing to long detours.','[{"question":"Who should visit Ratnapura?","answer":"Ratnapura suits gem, rainforest, waterfall, and offbeat-travel interests more than a standard first-time route."}]','Plan a Ratnapura Extension','Add Ratnapura to a specialist private route.','Sabaragamuwa Province','24-31 C','Gems and Rainforest','1-2 days',NULL,NULL,NULL,'Ratnapura Travel Guide for Gems, Rainforest, and Private Tours','Plan Ratnapura gem stops, rainforest links, waterfalls, Adam''s Peak routes, and private inland transfers.',NULL,0,30,1),
('Ampara','ampara','Eastern inland and coastal district with Kumana access, Arugam Bay links, temples, lagoons, and offbeat nature routes.','Ampara is best used for custom east and south-east itineraries, especially around Arugam Bay, Kumana, and lesser-known cultural sites.','It supports long-tail east-coast, wildlife, lagoon, and offbeat itinerary intent.','Kumana National Park access, Arugam Bay links, lagoons, temples, coastal wetlands, and regional drives.','May to September is useful for east-coast routing; wildlife timing varies by park.','Access is by private road from Ella, Yala, Arugam Bay, or the east coast.','Use as part of a custom south-east route, not a default overnight.','Simple hotels, nature lodges, and Arugam Bay-based stays.','Distances are long, so include Ampara only when the route has a clear purpose.','[{"question":"Is Ampara for first-time visitors?","answer":"Usually no. It is better for custom wildlife, east-coast, or repeat-visitor itineraries."}]','Plan a South-East Route','Use Ampara for custom nature and east-coast travel.','Eastern Province','27-34 C','Offbeat East and Wildlife','1-2 days',NULL,NULL,NULL,'Ampara Travel Guide for South-East Sri Lanka Routes','Plan Ampara, Kumana, Arugam Bay links, lagoons, and private south-east Sri Lanka route support.',NULL,0,31,1)
