INSERT INTO tours
(name, slug, excerpt, intro, highlights, sample_itinerary, pricing_notes, price_from, price_to, price_currency, price_unit, vehicle_options, faq_json, cta_title, cta_text, hero_image, og_image, meta_title, meta_description, canonical_url, is_featured, sort_order, is_published)
VALUES
('Classic Sri Lanka Private Tour Package','classic-sri-lanka-private-tour-package','A flexible private package for first-time visitors covering culture, hill country, wildlife, and beach time.','This package is the broadest fit for Europe, American, Australian, and long-haul visitors who want Sri Lanka''s classic route without losing comfort.','Sigiriya, Kandy, tea country, Ella, safari, Galle, south coast, private chauffeur, flexible hotels.','Typical timing: 10 to 14 days. Day 1 airport or Negombo. Days 2-4 Cultural Triangle. Days 5-7 Kandy and tea country. Days 8-10 safari and south coast. Extend to 14 days for beach and wellness.','Final pricing depends on hotel level, vehicle, guiding, park fees, and season. Attraction entry fees and hotels can be quoted separately.',950.00,2850.00,'USD','per couple land services','Sedan for couples, KDH van for families, Hiace for groups. Upgrade options available.','[{"question":"Can this package be shortened?","answer":"Yes. It works as 7, 10, 12, or 14 days depending on flights and preferred pace."}]','Plan a Classic Private Tour','Share your dates and we will shape the best-paced classic route.',NULL,NULL,'Classic Sri Lanka Private Tour Package','Book a classic private Sri Lanka package with culture, tea country, safari, beaches, timings, attractions, and chauffeur support.',NULL,1,10,1),
('Sri Lanka 10 Day Itinerary Package','sri-lanka-10-day-itinerary-package','The strongest first-time route for travelers who want depth without a two-week trip.','Ten days gives enough time for Sigiriya, Kandy, Ella, safari, and Galle or the south coast with private transport.','Airport, Sigiriya, Kandy, Nuwara Eliya or Ella, Yala or Udawalawe, Galle, beach or Colombo.','Typical timing: 10 days / 9 nights. Drive blocks are kept mostly between 2 and 4.5 hours. Add one scenic train segment if seats and timing work.','Quote after hotel level, passenger count, and safari plan are confirmed.',850.00,2200.00,'USD','per couple land services','Sedan, SUV, KDH van, or Hiace depending on group size.','[{"question":"Is 10 days enough for Sri Lanka?","answer":"Yes for a balanced first trip, as long as the route avoids too many one-night stops."}]','Plan 10 Days in Sri Lanka','Build a practical 10 day private route.',NULL,NULL,'Sri Lanka 10 Day Private Itinerary Package','Plan a 10 day Sri Lanka private tour with Sigiriya, Kandy, Ella, safari, Galle, timings, attractions, and chauffeur service.',NULL,1,20,1),
('Sri Lanka 14 Day Grand Tour Package','sri-lanka-14-day-grand-tour-package','A two-week private package for long-haul travelers who want culture, wildlife, hill country, and real beach time.','Fourteen days is the most comfortable classic Sri Lanka duration for Europe, North America, and Australia because it reduces rushed transfers.','Negombo, Sigiriya, Anuradhapura or Polonnaruwa, Kandy, Nuwara Eliya, Ella, Yala or Udawalawe, Galle, beach finish.','Typical timing: 14 days / 13 nights. Two-night bases are prioritized. Beach ending is adjusted by month: south/west in Nov-Apr, east in May-Sep.','Pricing depends heavily on hotel class and beach resort choice.',1250.00,4200.00,'USD','per couple land services','Comfort sedan, premium sedan, van, or luxury vehicle options.','[{"question":"Why choose 14 days?","answer":"It gives enough time for two-night stays, beach rest, wildlife, and heritage without forcing daily hotel changes."}]','Plan a 14 Day Grand Tour','Create a slower high-value Sri Lanka route.',NULL,NULL,'Sri Lanka 14 Day Grand Tour Package','Plan a 14 day private Sri Lanka package with attractions, route timings, hotels, safari, beaches, and private chauffeur travel.',NULL,1,30,1),
('Sri Lanka Honeymoon Package','sri-lanka-honeymoon-package','A private honeymoon package with boutique hotels, scenic travel, wildlife, beach time, and slower pacing.','This package avoids the common mistake of overloading honeymoon routes. It keeps the romantic stops, views, and beach time while reducing tiring transfers.','Sigiriya views, Kandy culture, tea country, Ella scenery, private safari, Galle Fort, Tangalle or Bentota beach.','Typical timing: 10 to 14 days. Keep at least two slow stays and one beach finish. Upgrade to villas or boutique suites where it matters most.','Pricing varies by boutique hotel and beach property level.',1350.00,5200.00,'USD','per couple land services','Premium car, SUV, or luxury van with private chauffeur.','[{"question":"Can the honeymoon route include Maldives?","answer":"Yes. Sri Lanka can be planned as the culture and wildlife section before a Maldives beach extension."}]','Plan a Sri Lanka Honeymoon','Design a romantic route with the right pace.',NULL,NULL,'Sri Lanka Honeymoon Package with Private Driver','Plan a private Sri Lanka honeymoon with boutique hotels, safari, tea country, Galle, beaches, timings, and chauffeur support.',NULL,1,40,1),
('Sri Lanka Family Tour Package','sri-lanka-family-tour-package','A family-friendly private package with easy pacing, wildlife, pools, beach time, and sensible transfer lengths.','Family trips work best when the itinerary protects energy. This package uses private vehicle support, child-friendly wildlife stops, and fewer hotel changes.','Negombo, Sigiriya, Kandy, Udawalawe, Galle, Bentota or south coast beach.','Typical timing: 8 to 12 days. Keep morning sightseeing, pool breaks, and two-night stays where possible.','Quote after ages, hotel style, room setup, and vehicle size are known.',1100.00,3600.00,'USD','per family land services','KDH van, Hiace, child-seat friendly vehicle options by request.','[{"question":"Which safari is best for families?","answer":"Udawalawe is often the easiest family safari because elephants are relatively reliable and routes are practical."}]','Plan a Family Tour','Create a comfortable family route.',NULL,NULL,'Sri Lanka Family Tour Package with Private Driver','Plan a private family Sri Lanka package with wildlife, culture, beach time, timings, attractions, and comfortable vehicle support.',NULL,1,50,1),
('Sri Lanka Wildlife Safari Package','sri-lanka-wildlife-safari-package','A wildlife-focused private package linking elephants, leopards, birding, rainforest, and nature lodges.','This package is for travelers who care more about wildlife quality than ticking off every classic city. It can focus on Yala, Udawalawe, Wilpattu, Minneriya, Bundala, Sinharaja, or Kumana.','Yala, Udawalawe, Wilpattu, Minneriya or Kaudulla, Bundala, Sinharaja, Kumana.','Typical timing: 7 to 12 days. Early safari starts, slower transfer days, and specialist guides are prioritized.','Park fees, jeep fees, guides, and lodges vary by park and season.',1250.00,4300.00,'USD','per couple land services','Private vehicle plus park jeep arrangements.','[{"question":"Can leopard sightings be guaranteed?","answer":"No. The route can improve chances, but ethical wildlife travel never guarantees sightings."}]','Plan a Wildlife Safari','Build a realistic Sri Lanka safari route.',NULL,NULL,'Sri Lanka Wildlife Safari Package','Plan Sri Lanka wildlife safaris with Yala, Udawalawe, Minneriya, Wilpattu, Bundala, timings, attractions, and private transfers.',NULL,1,60,1),
('Luxury Sri Lanka Slow Travel Package','luxury-sri-lanka-slow-travel-package','A high-comfort private package for fewer stops, better hotels, curated guiding, villas, and relaxed days.','Luxury Sri Lanka works best when the route is selective. This package favors depth, privacy, and better properties over constant movement.','Boutique Sigiriya, Kandy or tea country, private villa or fort hotel, luxury beach or wellness retreat.','Typical timing: 10 to 15 days. Fewer bases, private guiding days, wellness time, and beach endings are built in.','Luxury pricing depends on property selection, guide level, and peak-season availability.',2500.00,9000.00,'USD','per couple land services excluding hotels unless quoted','Premium sedan, SUV, luxury van, or special vehicle by request.','[{"question":"Is luxury travel in Sri Lanka about hotels only?","answer":"No. The biggest gains come from better pacing, better guides, private transfers, and selective experiences."}]','Plan Luxury Sri Lanka','Create a high-comfort private journey.',NULL,NULL,'Luxury Sri Lanka Private Tour Package','Plan a luxury private Sri Lanka package with boutique hotels, villas, wellness, private guides, timings, and slower travel design.',NULL,1,70,1)
