INSERT INTO itineraries
(name, slug, days, excerpt, intro, highlights, route_summary, nearby_travel_times, works_well_with, best_for, travel_notes, pricing_notes, vehicle_options, price_from, price_to, price_currency, price_unit, faq_json, cta_title, cta_text, hero_image, og_image, meta_title, meta_description, canonical_url, is_featured, sort_order, is_published)
VALUES
('Sri Lanka Itinerary 5 Days','sri-lanka-itinerary-5-days',5,'A compact private route for short stays covering airport, Sigiriya or Kandy, hill scenery, and Galle or Colombo return.','Five days is short for Sri Lanka, so this route prioritizes private transfers and avoids overloading the island.','Airport recovery, one heritage anchor, one scenic section, one beach or city finish.','Airport/Negombo -> Sigiriya or Kandy -> Nuwara Eliya or Ella glimpse -> Galle or Colombo.','Airport to Sigiriya 4-5 hours; Sigiriya to Kandy 2.5-3.5 hours; Kandy to Galle 4-5.5 hours by road depending on stops.','Works with Colombo, Negombo, Sigiriya, Kandy, Galle.','Short stopovers, business-leisure trips, repeat visitors with limited time.','Use this only when flights force a short route. A 7 or 10 day itinerary is stronger for first visits.','Pricing depends on hotel class, route choice, and vehicle.','Sedan or van depending on group size.',550.00,1450.00,'USD','per couple land services','[{"question":"Is 5 days enough for Sri Lanka?","answer":"It is enough for a focused private route, but not for a full island experience."}]','Plan 5 Days in Sri Lanka','Build the best possible short private route.',NULL,NULL,'Sri Lanka 5 Day Itinerary with Private Driver','Plan a compact 5 day Sri Lanka private itinerary with realistic timings, key attractions, and chauffeur transport.',NULL,0,5,1),
('Sri Lanka Itinerary 7 Days','sri-lanka-itinerary-7-days',7,'A practical one-week route for culture, hill country, safari or Galle, and private road timing.','Seven days is the shortest duration that can still feel like a proper Sri Lanka private trip if the route is disciplined.','Sigiriya, Kandy, hill country, safari or Galle, airport return.','Airport/Negombo -> Sigiriya -> Kandy -> Ella or Nuwara Eliya -> Udawalawe or Galle -> Colombo.','Most transfer blocks are 2.5-4.5 hours; avoid adding both far north and deep south in one week.','Works with Sigiriya, Kandy, Ella, Udawalawe, Galle, Negombo.','First-time visitors, couples, families, travelers with one week.','Choose either safari or beach depth, not both at full strength.','Pricing depends on hotels, safari, and route.','Sedan, KDH van, or Hiace.',700.00,1900.00,'USD','per couple land services','[{"question":"What should I skip in a 7 day Sri Lanka trip?","answer":"Skip remote detours and keep the route to one heritage base, one hill-country section, and one wildlife or coast finish."}]','Plan 7 Days in Sri Lanka','Create a focused one-week private route.',NULL,NULL,'Sri Lanka 7 Day Itinerary with Private Driver','Plan a 7 day Sri Lanka itinerary with culture, hill country, safari or Galle, timings, attractions, and private chauffeur travel.',NULL,1,10,1),
('Sri Lanka Itinerary 10 Days','sri-lanka-itinerary-10-days',10,'The strongest first-time route length for culture, hill country, wildlife, and south-coast heritage.','Ten days balances variety and comfort for most long-haul travelers. It gives time for the Cultural Triangle, Kandy, Ella or Nuwara Eliya, safari, and Galle or beach.','Sigiriya, Kandy, train or tea country, Ella, safari, Galle, south coast.','Airport/Negombo -> Sigiriya -> Kandy -> Nuwara Eliya/Ella -> Yala or Udawalawe -> Galle/Mirissa -> Colombo.','Airport to Sigiriya 4-5 hours; Kandy to Nuwara Eliya 2.5-3.5 hours; Ella to Yala 2.5-3.5 hours; Galle to airport 2-3 hours by expressway.','Works with Sigiriya, Kandy, Nuwara Eliya, Ella, Yala, Udawalawe, Galle, Mirissa.','First-time long-haul travelers, couples, families, private chauffeur tours.','Use two-night bases where possible and avoid too many optional stops on transfer days.','Quote after hotel class, vehicle, and safari choices.','Sedan, SUV, KDH van, or Hiace.',850.00,2400.00,'USD','per couple land services','[{"question":"Is 10 days the best first Sri Lanka itinerary?","answer":"For many travelers, yes. It gives enough time for the main regions without needing a full two weeks."}]','Plan 10 Days in Sri Lanka','Build a balanced first-time private route.',NULL,NULL,'Sri Lanka 10 Day Itinerary with Private Driver','Plan a 10 day Sri Lanka private itinerary with Sigiriya, Kandy, Ella, safari, Galle, timings, attractions, and chauffeur support.',NULL,1,20,1),
('Sri Lanka Itinerary 12 Days','sri-lanka-itinerary-12-days',12,'A better-paced route for travelers who want the classic highlights plus more beach or wellness time.','Twelve days gives space to reduce one-night stops and add either beach, wellness, or a deeper Cultural Triangle day.','Cultural Triangle, Kandy, tea country, Ella, safari, Galle, beach finish.','Negombo -> Sigiriya -> Kandy -> Nuwara Eliya -> Ella -> Yala/Udawalawe -> Galle -> Bentota/Tangalle/Mirissa.','Most drives sit under 4.5 hours when bases are chosen carefully.','Works with classic, family, honeymoon, luxury, and beach routes.','Europe, American, Australian, and long-haul visitors who want comfort.','Use the extra two days to slow down, not to add distant detours.','Pricing depends on property level and beach choice.','Comfort sedan, van, or premium vehicle.',1050.00,3200.00,'USD','per couple land services','[{"question":"Why choose 12 days instead of 10?","answer":"Twelve days improves pacing and adds room for real beach or wellness time."}]','Plan 12 Days in Sri Lanka','Create a better-paced private itinerary.',NULL,NULL,'Sri Lanka 12 Day Itinerary with Private Driver','Plan a 12 day Sri Lanka route with culture, hill country, safari, beaches, wellness time, attractions, and private driver support.',NULL,1,30,1),
('Sri Lanka Itinerary 14 Days','sri-lanka-itinerary-14-days',14,'A two-week grand route for travelers who want the full island arc without rushing.','Fourteen days is ideal for long-haul travelers because it allows two-night stays, a proper beach finish, and optional deeper heritage or nature.','Negombo, Sigiriya, ancient city, Kandy, tea country, Ella, safari, Galle, beach finish.','Negombo -> Sigiriya -> Polonnaruwa/Anuradhapura -> Kandy -> Nuwara Eliya -> Ella -> Yala/Udawalawe -> Galle -> beach -> airport.','Longer drives are buffered with two-night stays. Beach choice changes by season.','Works with honeymoon, luxury, family, wildlife, wellness, and classic packages.','Europe, North America, Australia, and travelers seeking a complete first trip.','Protect the final beach days and avoid turning the route into daily hotel changes.','Quote after final hotel class and seasonal coast choice.','Sedan, premium sedan, SUV, KDH van, or Hiace.',1250.00,4200.00,'USD','per couple land services','[{"question":"What is the best Sri Lanka itinerary length?","answer":"Fourteen days is the best all-round length for a comfortable full first trip."}]','Plan 14 Days in Sri Lanka','Build a complete private island route.',NULL,NULL,'Sri Lanka 14 Day Itinerary with Private Driver','Plan a 14 day Sri Lanka itinerary with culture, tea country, safari, beaches, timings, attractions, and private chauffeur service.',NULL,1,40,1),
('Sri Lanka Honeymoon Itinerary 12 Days','sri-lanka-honeymoon-itinerary-12-days',12,'A romantic private route with fewer hotel changes, boutique stays, scenery, wildlife, Galle, and beach time.','This honeymoon itinerary prioritizes comfort, privacy, views, and slower pacing over trying to see every stop.','Sigiriya views, Kandy or tea country, Ella scenery, private safari, Galle Fort, Tangalle or Bentota beach.','Airport/Negombo -> Sigiriya -> Kandy/tea country -> Ella -> Yala or Udawalawe -> Galle -> Tangalle/Bentota.','Keep key drives under 4 hours where possible and use two-night stays.','Works with honeymoon, luxury, wellness, and boutique hotel routes.','Couples, honeymooners, anniversary trips, high-comfort private travel.','Choose properties carefully and leave open time for weather and rest.','Depends on hotel class and beach property.','Premium car, SUV, or luxury van.',1450.00,5200.00,'USD','per couple land services','[{"question":"Can this be made more luxury?","answer":"Yes. Upgrade the vehicle, hotels, guides, safari lodge, and beach stay while keeping the same slower route logic."}]','Plan a Sri Lanka Honeymoon','Create a romantic private route.',NULL,NULL,'Sri Lanka Honeymoon Itinerary 12 Days','Plan a 12 day Sri Lanka honeymoon with boutique hotels, Sigiriya, tea country, safari, Galle, beach time, and private driver support.',NULL,1,50,1),
('Sri Lanka Family Itinerary 10 Days','sri-lanka-family-itinerary-10-days',10,'A family-friendly private route with culture, elephants, beach or Galle time, and sensible transfer lengths.','This route protects family energy with private vehicle support, realistic starts, and a mix of animals, pools, culture, and beach.','Negombo, Sigiriya, Kandy, Udawalawe, Galle, Bentota or south coast.','Negombo -> Sigiriya -> Kandy -> Udawalawe -> Galle/Bentota -> airport.','Most drives are kept manageable, with safari and pool time planned around children.','Works with family packages, school holidays, and multi-generational groups.','Families with children, grandparents, and comfort-focused groups.','Avoid back-to-back long driving days. Choose hotels with pools.','Depends on room setup, vehicle, and hotel class.','KDH van or Hiace recommended for families.',1200.00,3600.00,'USD','per family land services','[{"question":"Which Sri Lanka route is best for kids?","answer":"A route with Sigiriya, elephants, Kandy, and a beach finish usually works best when it avoids daily hotel changes."}]','Plan a Family Itinerary','Build a child-friendly private route.',NULL,NULL,'Sri Lanka Family Itinerary 10 Days','Plan a 10 day Sri Lanka family itinerary with elephants, culture, beaches, timings, attractions, and private vehicle comfort.',NULL,1,60,1),
('Sri Lanka Wildlife Itinerary 9 Days','sri-lanka-wildlife-itinerary-9-days',9,'A wildlife-focused route linking elephants, leopards, birding, and nature without ignoring transfer reality.','This itinerary is for travelers who want safari and nature as the central purpose of the trip.','Minneriya/Kaudulla, Udawalawe, Yala, Bundala, optional Sinharaja or Wilpattu.','Negombo -> Sigiriya/Habarana -> Udawalawe -> Yala/Tissamaharama -> Galle or Tangalle -> airport.','Safari days require early starts; avoid long drives after late afternoon game drives.','Works with wildlife package, photographers, families, and nature travelers.','Wildlife lovers, photographers, families, safari-focused travelers.','Build realistic expectations and choose parks by season and route, not name alone.','Park fees and jeeps are variable and quoted separately.','Private road vehicle plus park jeep arrangements.',1250.00,3900.00,'USD','per couple land services','[{"question":"Can I see both leopards and elephants?","answer":"Yes, a route can include Yala for leopard search and Udawalawe or Minneriya for elephants, but sightings remain natural and cannot be guaranteed."}]','Plan Wildlife Sri Lanka','Create a safari-first private route.',NULL,NULL,'Sri Lanka Wildlife Itinerary 9 Days','Plan a 9 day Sri Lanka wildlife itinerary with Yala, Udawalawe, Minneriya, timings, attractions, and private transfers.',NULL,1,70,1),
('Sri Lanka South Coast Itinerary 8 Days','sri-lanka-south-coast-itinerary-8-days',8,'A beach, surf, Galle, whale watching, and safari-friendly route for travelers prioritizing the south.','This route works for travelers who do not need the full Cultural Triangle and want a warmer coastal rhythm.','Galle, Unawatuna, Weligama, Mirissa, Tangalle, Udawalawe or Yala.','Airport/Negombo -> Galle -> Weligama/Mirissa -> Tangalle -> Udawalawe/Yala -> airport or Colombo.','Coastal drives are usually 30 minutes to 3 hours; safari detours add longer transfer blocks.','Works with surf, beach, family, honeymoon, and short-stay routes.','Beach-focused travelers, surfers, couples, families.','Best in south-coast season from November to April.','Depends on beach hotel and safari choice.','Sedan, SUV, or van.',750.00,2400.00,'USD','per couple land services','[{"question":"Can I skip the Cultural Triangle?","answer":"Yes, if the traveler mainly wants beach, surf, Galle, and wildlife. It is a different style of trip."}]','Plan the South Coast','Build a beach-first Sri Lanka route.',NULL,NULL,'Sri Lanka South Coast Itinerary 8 Days','Plan an 8 day south coast Sri Lanka itinerary with Galle, Mirissa, Weligama, Tangalle, safari, timings, and private driver support.',NULL,0,80,1),
('Sri Lanka East Coast Itinerary 10 Days','sri-lanka-east-coast-itinerary-10-days',10,'A May-September route linking the Cultural Triangle with Trincomalee, Passikudah, or Arugam Bay.','The east coast is essential for seasonal SEO because it can be the better beach choice when the south-west coast is rougher.','Sigiriya, Polonnaruwa, Trincomalee, Passikudah, Arugam Bay options.','Negombo -> Sigiriya -> Polonnaruwa -> Trincomalee or Passikudah -> optional Arugam Bay -> airport via inland route.','East-coast transfers are longer; keep two or three nights at the beach base.','Works with mid-year beach routes, families, surf, and repeat visitors.','May to September travelers, beach seekers, families, surfers.','Do not add every east-coast beach in one short itinerary.','Quote after beach base and hotel class are chosen.','Sedan, SUV, or van.',950.00,3000.00,'USD','per couple land services','[{"question":"When should I choose the east coast?","answer":"The east coast is usually strongest from May to September, especially for Trincomalee and Passikudah beach time."}]','Plan the East Coast','Build a seasonal beach route.',NULL,NULL,'Sri Lanka East Coast Itinerary 10 Days','Plan a 10 day Sri Lanka east coast itinerary with Sigiriya, Trincomalee, Passikudah, Arugam Bay, timings, and private transfers.',NULL,0,90,1),
('Sri Lanka Luxury Itinerary 11 Days','sri-lanka-luxury-itinerary-11-days',11,'A selective high-comfort route with premium stays, private guiding, safari, wellness, and fewer hotel changes.','This route is for travelers who spend more for better pacing, hotels, and guides rather than more stops.','Sigiriya luxury lodge, Kandy or tea bungalow, private safari lodge, Galle boutique stay, beach or wellness finish.','Airport -> Sigiriya -> tea country -> safari lodge -> Galle/Tangalle/Bentota -> airport.','Use fewer bases and buffer the longer road days with premium stays.','Works with luxury, honeymoon, wellness, and older travelers.','High-spend couples, families, anniversary trips, comfort-first travelers.','Luxury is most effective when the route is slower and selective.','Quote by property selection and guide level.','Premium vehicle options.',2800.00,9500.00,'USD','per couple land services excluding hotels unless quoted','[{"question":"What makes this itinerary luxury?","answer":"The route uses fewer stops, better properties, private guiding, more rest, and higher-comfort transfers."}]','Plan Luxury Sri Lanka','Design a slower premium route.',NULL,NULL,'Sri Lanka Luxury Itinerary 11 Days','Plan an 11 day luxury Sri Lanka itinerary with boutique stays, safari, wellness, Galle, beaches, timings, and private chauffeur support.',NULL,1,100,1),
('Sri Lanka Birding and Nature Itinerary 12 Days','sri-lanka-birding-nature-itinerary-12-days',12,'A specialist nature route for rainforest, wetlands, highlands, birding, and safari habitats.','This itinerary is for travelers who need specialist nature pacing and good guide matching.','Sinharaja, Bundala, Horton Plains, Udawalawe, Yala, Mannar or Kumana options.','Airport -> Sinharaja/Ratnapura -> Udawalawe -> Bundala/Yala -> Horton Plains or Kumana extension -> Galle/airport.','Nature days need early starts and weather buffers.','Works with birding, rainforest, photography, and specialist wildlife interests.','Birders, photographers, rainforest travelers, repeat visitors.','Confirm guide quality, seasonal access, and target species before finalizing.','Specialist guiding and park fees quoted separately.','Private vehicle plus specialist guide arrangements.',1800.00,5600.00,'USD','per couple land services','[{"question":"Can this be customized for target birds?","answer":"Yes. The route should be adjusted around target species, season, and habitat access."}]','Plan a Nature Itinerary','Build a specialist wildlife and birding route.',NULL,NULL,'Sri Lanka Birding and Nature Itinerary 12 Days','Plan a 12 day Sri Lanka birding and nature itinerary with rainforest, wetlands, highlands, safari parks, timings, and private support.',NULL,0,110,1)
