    why_sri_lanka = IF(COALESCE(why_sri_lanka, '') = '', VALUES(why_sri_lanka), why_sri_lanka),
    recommended_itinerary = IF(COALESCE(recommended_itinerary, '') = '', VALUES(recommended_itinerary), recommended_itinerary),
    travel_info = IF(COALESCE(travel_info, '') = '', VALUES(travel_info), travel_info),
    best_time = IF(COALESCE(best_time, '') = '', VALUES(best_time), best_time),
    faq_json = IF(COALESCE(faq_json, '') = '', VALUES(faq_json), faq_json),
    meta_title = IF(COALESCE(meta_title, '') = '', VALUES(meta_title), meta_title),
    meta_description = IF(COALESCE(meta_description, '') = '', VALUES(meta_description), meta_description),
    cta_title = IF(COALESCE(cta_title, '') = '', VALUES(cta_title), cta_title),
    cta_text = IF(COALESCE(cta_text, '') = '', VALUES(cta_text), cta_text),
    sort_order = IF(sort_order = 0, VALUES(sort_order), sort_order),
    is_published = GREATEST(is_published, VALUES(is_published));

INSERT INTO blog_posts
(category_id, title, slug, excerpt, content, hero_image, og_image, author, meta_title, meta_description, canonical_url, sidebar_widgets_json, is_featured, is_published, published_at)
VALUES
((SELECT id FROM blog_categories WHERE slug='itineraries' LIMIT 1),'The Best Sri Lanka Itinerary Length: 7, 10, 12, or 14 Days','best-sri-lanka-itinerary-length','How to choose the right Sri Lanka trip length based on flights, pace, wildlife, beaches, and private-driver routing.','<p>Most Sri Lanka itinerary problems start with the wrong duration. The island looks small on a map, but mountain roads, temple visits, safaris, train segments, and beach time all need space.</p><h2>Quick answer</h2><p>Choose 7 days only for a focused first taste. Choose 10 days for the best short first trip. Choose 12 days if you want better pacing. Choose 14 days if you are flying long haul from Europe, North America, or Australia and want culture, wildlife, hill country, and real beach time.</p><h2>What changes by duration</h2><p>A 7 day route should usually include one heritage base, one hill-country section, and one wildlife or coast finish. A 10 day route can include Sigiriya, Kandy, Ella, safari, Galle, and a short beach stay. A 14 day route can use two-night bases and protect the final beach days.</p><h2>Private-driver planning note</h2><p>The right route is not about adding every famous place. It is about placing the long drives where they do the least damage. A private chauffeur route lets you use scenic stops, early starts, and flexible hotel timing instead of forcing fixed group-tour pacing.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Best Sri Lanka Itinerary Length: 7, 10, 12, or 14 Days','Compare 7, 10, 12, and 14 day Sri Lanka itineraries with practical routing advice for private tours.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-06-24 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='planning' LIMIT 1),'Sri Lanka Private Driver Guide: What to Expect','sri-lanka-private-driver-guide','What private chauffeur-guided travel in Sri Lanka includes, what it does not include, and how to plan it well.','<p>A private driver in Sri Lanka is not only transport. For many travelers, it is the difference between a route that looks good on paper and a route that actually works on the road.</p><h2>What a private driver helps with</h2><p>Your driver handles airport pickup, road timing, hotel-to-hotel transfers, local stops, and flexibility when weather, train tickets, or safari times change. The best private routes also use local knowledge to avoid overloaded days.</p><h2>What to clarify before booking</h2><p>Confirm vehicle type, luggage space, daily route, driver accommodation, fuel, parking, highway tolls, and whether specialist site guides are included. At places like Sigiriya, Anuradhapura, and wildlife parks, a separate licensed guide may still add value.</p><h2>Who should book one</h2><p>Couples, families, older travelers, photographers, and long-haul visitors usually get the most benefit. Public transport can be memorable, but it is less suitable when you need comfort, luggage support, child-friendly pacing, or multi-region routing.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Private Driver Guide','Learn what to expect when hiring a private driver in Sri Lanka, including vehicle choices, routing, timings, and planning tips.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-07-01 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='destinations' LIMIT 1),'Sigiriya or Pidurangala: Which Should You Climb?','sigiriya-or-pidurangala','A practical guide to choosing Sigiriya, Pidurangala, or both, with timing and route advice.','<p>Sigiriya and Pidurangala are often discussed as if they are interchangeable. They are not. Sigiriya is the archaeological site. Pidurangala is the viewpoint that gives you the famous sunrise view back toward Lion Rock.</p><h2>Choose Sigiriya for history</h2><p>Sigiriya has the water gardens, frescoes, Mirror Wall, Lion Gate, and summit palace ruins. It is the essential choice for travelers who want the UNESCO story and the full Cultural Triangle experience.</p><h2>Choose Pidurangala for the view</h2><p>Pidurangala is better for sunrise photos and a quieter climb. It is shorter, rougher near the top, and less formal than Sigiriya. It does not replace the archaeology of Sigiriya, but it complements it beautifully.</p><h2>Best plan</h2><p>Stay two nights near Sigiriya. Climb Pidurangala at sunrise, rest, then visit Sigiriya early or later in the day. Add Dambulla or an elephant safari only if the pacing still feels comfortable.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sigiriya or Pidurangala: Which Should You Climb?','Compare Sigiriya and Pidurangala with practical advice on views, history, timing, and private Cultural Triangle routing.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-07-08 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='experiences' LIMIT 1),'Yala vs Udawalawe: Which Safari Is Better?','yala-vs-udawalawe-safari','How to choose between Yala and Udawalawe based on leopards, elephants, children, route timing, and expectations.','<p>Yala and Udawalawe are both excellent, but they solve different travel problems. The best safari is the one that fits your route, your expectations, and your group.</p><h2>Choose Yala for leopard-focused safari</h2><p>Yala is Sri Lanka''s most famous safari name and a strong choice for travelers hoping for leopard sightings. It also pairs well with Ella, Tangalle, and Galle. The tradeoff is popularity and busier park conditions.</p><h2>Choose Udawalawe for elephants and families</h2><p>Udawalawe is usually easier for families and first-time safari travelers. Elephant sightings tend to be more consistent, the open terrain is easier to watch, and route planning from Ella or the south coast is straightforward.</p><h2>Best planning advice</h2><p>Do not chase park names only. Check your route, month, hotel location, and tolerance for early starts. Wildlife is never guaranteed, so a good plan balances safari with rest and onward travel.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Yala vs Udawalawe Safari','Compare Yala and Udawalawe safaris for leopards, elephants, families, timings, and private Sri Lanka route planning.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-07-15 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='itineraries' LIMIT 1),'A Realistic 10 Day Sri Lanka Itinerary for First-Time Visitors','realistic-10-day-sri-lanka-itinerary','A balanced 10 day route with Sigiriya, Kandy, tea country, safari, Galle, and private-driver timing.','<p>Ten days is the strongest first-trip length for many Sri Lanka visitors. It gives enough variety without turning every day into a hotel change.</p><h2>Suggested route</h2><p>Start with one arrival night near Negombo or Colombo. Continue to Sigiriya for two nights, then Kandy for culture, Nuwara Eliya or Ella for tea country, one safari stop at Yala or Udawalawe, and finish with Galle or a south-coast beach.</p><h2>Why this works</h2><p>The route covers heritage, hills, wildlife, and coast. It also keeps the biggest drives in a sensible order. The private driver helps with early starts, luggage, station timing if you add a train segment, and stops that fit the day.</p><h2>What to avoid</h2><p>Do not add Anuradhapura, Trincomalee, Jaffna, and the south coast into the same 10 days. That route may look impressive, but it will feel rushed.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Realistic 10 Day Sri Lanka Itinerary','Plan a realistic 10 day Sri Lanka itinerary with private driver timings, attractions, culture, safari, Galle, and beaches.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-07-22 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='source-markets' LIMIT 1),'Sri Lanka Tours from the UK: Best Route for Winter Sun','sri-lanka-tours-from-uk-winter-sun','A UK-focused planning guide for winter sun, beaches, wildlife, culture, and two-week private routes.','<p>UK travelers are one of Sri Lanka''s largest source markets, and the classic winter route is still popular for good reason. It combines warm weather, heritage, tea country, wildlife, and beach time.</p><h2>Best duration</h2><p>For most UK travelers, 12 to 14 days is ideal. The extra time protects you from long-haul fatigue and gives space for two-night stays instead of daily movement.</p><h2>Best route style</h2><p>Use Negombo or Colombo for arrival recovery, then Sigiriya, Kandy, tea country, Ella, Yala or Udawalawe, Galle, and a south or west coast beach finish. November to April usually fits the south and west coasts best.</p><h2>Family and couple notes</h2><p>Families should protect pool time and use easier safari pacing. Couples can upgrade the route with boutique hotels, Tangalle, wellness, or a Maldives extension.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Tours from the UK for Winter Sun','Plan Sri Lanka tours from the UK with winter sun, 12 to 14 day routes, wildlife, tea country, beaches, and private driver support.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-07-29 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='source-markets' LIMIT 1),'Sri Lanka Tours from Australia: Family, Surf, and Wildlife Planning','sri-lanka-tours-from-australia-family-surf-wildlife','A practical Australia-focused route guide for families, surf travelers, wildlife lovers, and school holidays.','<p>Australian travelers often combine Sri Lanka''s classic route with surf, family comfort, and wildlife. The private-driver format works especially well when children, luggage, and flexible timing matter.</p><h2>Best duration</h2><p>Ten to fourteen days works well. Shorter trips should stay focused around Sigiriya, Kandy, wildlife, and the south coast. Longer trips can add east-coast surf or a slower beach stay.</p><h2>Surf planning</h2><p>Weligama is a strong beginner surf base on the south coast. Ahangama and Midigama suit progressing surfers. Arugam Bay is the better-known east-coast surf base in the mid-year season.</p><h2>Family route idea</h2><p>Use Negombo, Sigiriya, Kandy, Udawalawe, Galle, and Bentota or Weligama. Keep two-night stays where possible and protect pool time after longer drives.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Tours from Australia','Plan Sri Lanka tours from Australia with family routes, surf, wildlife, school holiday timing, beaches, and private driver support.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-08-05 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='source-markets' LIMIT 1),'Sri Lanka Tours from the USA: Why Two Weeks Works Best','sri-lanka-tours-from-usa-two-weeks','A US-focused guide to long-haul pacing, arrival recovery, classic routes, wildlife, beaches, and boutique stays.','<p>Travelers from the United States should treat Sri Lanka as a long-haul trip, not a quick checklist. Two weeks gives the route enough space to feel rewarding.</p><h2>Why 12 to 15 days is better</h2><p>Long flights make arrival recovery important. The route also crosses different regions: Cultural Triangle, hill country, wildlife parks, and beaches. Compressing everything into one week creates too many transfer-heavy days.</p><h2>Recommended route</h2><p>Start near Negombo, continue to Sigiriya, then Kandy, tea country or Ella, Yala or Udawalawe, Galle, and a beach or wellness finish. Luxury travelers should use fewer bases and better properties.</p><h2>Planning note</h2><p>Decide early whether the trip is wildlife-led, honeymoon-style, family-focused, or luxury slow travel. The best private route changes depending on that answer.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Tours from the USA','Plan Sri Lanka tours from the USA with two-week pacing, arrival recovery, wildlife, culture, beaches, and private chauffeur routes.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-08-12 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='destinations' LIMIT 1),'When to Choose Sri Lanka East Coast Beaches','when-to-choose-sri-lanka-east-coast-beaches','How Trincomalee, Passikudah, and Arugam Bay fit Sri Lanka routes from May to September.','<p>Many first-time travelers only hear about the south coast, but Sri Lanka''s east coast is essential for seasonal planning. From May to September, it can be the better beach choice.</p><h2>Best east-coast bases</h2><p>Trincomalee works well after Sigiriya and offers Nilaveli, Uppuveli, Pigeon Island, and Koneswaram Temple. Passikudah is more resort-focused and family-friendly. Arugam Bay is the surf and relaxed traveler option.</p><h2>Route logic</h2><p>The east coast pairs naturally with the Cultural Triangle. A practical route can use Negombo, Sigiriya, Polonnaruwa, Trincomalee or Passikudah, and then return inland. Arugam Bay pairs better with Ella or south-east wildlife routes.</p><h2>What to avoid</h2><p>Do not add the east coast as a one-night detour. The transfer times are too long. Stay at least two or three nights to make it worthwhile.</p>',NULL,NULL,'Island Culture Travels Editorial Team','When to Choose Sri Lanka East Coast Beaches','Plan Sri Lanka east coast beaches including Trincomalee, Passikudah, and Arugam Bay by season, route timing, and private transfers.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-08-19 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='planning' LIMIT 1),'Sri Lanka with Kids: Private Family Tour Planning Tips','sri-lanka-with-kids-family-tour-planning','Practical advice for family trips: drive times, elephants, pools, beaches, hotels, and private vehicle comfort.','<p>Sri Lanka can be excellent with children when the route is built around family energy rather than adult sightseeing ambition.</p><h2>Keep the route simple</h2><p>Two-night stays matter. Children usually enjoy elephants, short hikes, beaches, pools, trains, and simple cultural experiences more than long site lists.</p><h2>Best family anchors</h2><p>Negombo is useful for arrival recovery. Sigiriya adds culture and nature. Udawalawe is one of the easiest safari choices for elephants. Galle and Bentota work well for beach and comfort.</p><h2>Private vehicle benefits</h2><p>A private van gives space for bags, snacks, stops, naps, and flexible timing. It also helps when weather or tired children change the plan.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka with Kids: Family Tour Tips','Plan Sri Lanka with kids using private vehicle routes, realistic drive times, elephants, beaches, pools, and family-friendly hotels.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-08-26 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='experiences' LIMIT 1),'Kandy to Ella Train: When It Is Worth It and When to Skip It','kandy-to-ella-train-worth-it','A practical guide to using Sri Lanka''s famous train journey without damaging the rest of the itinerary.','<p>The Kandy to Ella train is famous for a reason, but it is not always the best choice for every traveler or every route.</p><h2>When it is worth it</h2><p>It is worth it when travelers want scenery, have enough time, and can secure suitable seats. It works best as part of a hill-country route with private vehicle support for luggage and hotel transfers.</p><h2>When to skip or shorten it</h2><p>Skip the full ride if the group has very limited time, young children who may struggle with the long journey, or a route that already has too many transfer-heavy days. A shorter scenic section can still deliver the experience.</p><h2>Best private-tour approach</h2><p>Use the train for the scenic value and the driver for everything else. This keeps luggage safe, simplifies station timing, and preserves flexibility if weather or delays change the plan.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Kandy to Ella Train: Is It Worth It?','Plan the Kandy to Ella train with private driver support, seat timing, luggage help, and alternatives for Sri Lanka itineraries.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-09-02 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='experiences' LIMIT 1),'Minneriya Elephant Gathering: How to Plan It from Sigiriya','minneriya-elephant-gathering-from-sigiriya','How to plan Minneriya or Kaudulla elephant safari timing from Sigiriya without overloading the day.','<p>The elephant gathering near Sigiriya is one of Sri Lanka''s most memorable wildlife experiences, but the best park choice can change.</p><h2>Minneriya or Kaudulla?</h2><p>Travelers often search for Minneriya, but local conditions may make Kaudulla the better choice on a given day. A good private plan stays flexible and uses current local advice.</p><h2>Best route pairing</h2><p>Stay near Sigiriya or Habarana for two nights. Use one day for the rock and one afternoon for safari. Add Dambulla or Polonnaruwa only if the timing stays comfortable.</p><h2>Season note</h2><p>The well-known Gathering period is usually July to October, but elephants move with water and conditions. Wildlife should always be planned with realistic expectations.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Minneriya Elephant Gathering from Sigiriya','Plan Minneriya or Kaudulla elephant safari from Sigiriya with seasonal timing, private transfers, and realistic wildlife expectations.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-09-09 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='planning' LIMIT 1),'Sri Lanka Monsoon Planning: Which Coast Should You Choose?','sri-lanka-monsoon-which-coast','A practical guide to choosing south, west, or east coast beach stops by travel month.','<p>Sri Lanka beach planning is seasonal. Choosing the wrong coast can turn a good itinerary into a wet and rough-sea beach stay.</p><h2>Simple rule</h2><p>For many travelers, the south and west coasts are strongest from November to April. The east coast is often stronger from May to September. Weather is never guaranteed, but this rule helps route design.</p><h2>South and west coast choices</h2><p>Galle, Unawatuna, Weligama, Mirissa, Tangalle, Bentota, and Hikkaduwa work well for classic winter routes.</p><h2>East coast choices</h2><p>Trincomalee, Nilaveli, Passikudah, and Arugam Bay are useful for mid-year routes. Because transfers are longer, stay at least two nights.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Monsoon Beach Planning','Choose the best Sri Lanka coast by month, including south, west, and east coast beach planning for private itineraries.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-09-16 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='itineraries' LIMIT 1),'Sri Lanka Honeymoon Route: What to Include and What to Skip','sri-lanka-honeymoon-route-what-to-include','How to build a romantic Sri Lanka honeymoon with scenery, wildlife, boutique hotels, and enough rest.','<p>A honeymoon itinerary should not feel like a race. Sri Lanka has enough variety for romance, scenery, wildlife, and beaches, but the best routes are selective.</p><h2>What to include</h2><p>Include one iconic heritage stop such as Sigiriya, one scenic highland section, one wildlife or nature experience, Galle or a boutique coastal town, and a beach finish.</p><h2>What to skip</h2><p>Skip excessive one-night stops, distant detours, and early starts on too many consecutive days. A romantic route needs space for slow mornings and good hotels.</p><h2>Best duration</h2><p>Ten to fourteen days is the sweet spot. Add luxury through pacing, hotel selection, and private guiding rather than by adding more places.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Honeymoon Route Planning','Plan a Sri Lanka honeymoon with boutique hotels, Sigiriya, tea country, safari, Galle, beaches, and private chauffeur pacing.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-09-23 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='itineraries' LIMIT 1),'Luxury Sri Lanka: Why Slower Routes Feel Better','luxury-sri-lanka-slower-routes','A high-spend travel planning guide explaining why fewer stops, better hotels, and private guiding improve the trip.','<p>Luxury Sri Lanka is not about adding every famous stop. It is about using the island''s variety without letting transfers dominate the holiday.</p><h2>Fewer bases, better days</h2><p>A slower route gives time for morning light, better meals, spa time, private guides, and flexible weather decisions. It also makes premium hotels worth the spend.</p><h2>Where to invest</h2><p>Invest in Sigiriya or Cultural Triangle lodges, tea-country bungalows, a private safari lodge, Galle boutique stays, beach villas, and expert guiding where context matters.</p><h2>Best route length</h2><p>Eleven to fifteen days works well. The route should have fewer hotel changes than a standard itinerary and should protect rest days.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Luxury Sri Lanka Slow Travel','Plan luxury Sri Lanka private tours with slower routing, boutique hotels, villas, safari lodges, wellness, and private chauffeur support.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-09-30 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='destinations' LIMIT 1),'Galle Fort: How to Use It in a South Coast Route','galle-fort-south-coast-route','How Galle Fort fits with Unawatuna, Hikkaduwa, Weligama, Mirissa, Tangalle, and airport transfers.','<p>Galle Fort is more than a photo stop. It is the heritage anchor of the south coast and one of the easiest places to make a beach route feel richer.</p><h2>Best timing</h2><p>Walk the fort in the morning or near sunset. Midday can be hot, and the best atmosphere comes when the light softens around the ramparts.</p><h2>Where to stay</h2><p>Stay inside the fort for boutique charm, in Unawatuna for beach access, in Hikkaduwa for a livelier reef town, or farther east for Weligama and Mirissa.</p><h2>Route role</h2><p>Use Galle after safari or before departure. The expressway makes it practical for the final stretch back to Colombo or the airport.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Galle Fort South Coast Route Guide','Plan Galle Fort with Unawatuna, Hikkaduwa, Weligama, Mirissa, Tangalle, and private south-coast transfers.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-10-07 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='experiences' LIMIT 1),'Sri Lanka Surf Planning: Weligama, Ahangama, Hikkaduwa, or Arugam Bay?','sri-lanka-surf-planning-weligama-ahangama-hikkaduwa-arugam-bay','How to choose the right Sri Lanka surf base by season, level, and itinerary style.','<p>Sri Lanka is a strong surf destination because different coasts work at different times. The right base depends on season and level.</p><h2>For beginners</h2><p>Weligama is one of the most practical beginner surf bases. It has lessons, a broad bay, and easy access to Mirissa and Galle.</p><h2>For progressing surfers</h2><p>Ahangama and Midigama suit travelers who want cafes, villas, and more varied breaks. Hikkaduwa is livelier and closer to Galle.</p><h2>For east-coast season</h2><p>Arugam Bay is the best-known east-coast surf base and usually fits mid-year routes. It is a longer detour, so do not add it casually to a short trip.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Surf Planning Guide','Compare Weligama, Ahangama, Hikkaduwa, and Arugam Bay for Sri Lanka surf trips by season, level, and private route timing.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-10-14 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='planning' LIMIT 1),'Sri Lanka Travel Costs: What Changes the Price of a Private Tour?','sri-lanka-private-tour-costs','A clear explanation of what affects Sri Lanka private tour pricing: hotels, vehicle, safari fees, guides, season, and route length.','<p>Private tour pricing in Sri Lanka changes because each route is built from several moving parts. A low quote and a high quote may include very different things.</p><h2>Main cost drivers</h2><p>Hotel level, vehicle type, number of travelers, route distance, safari jeep fees, attraction entrance fees, specialist guides, and travel season all affect the final price.</p><h2>What to compare</h2><p>Ask whether hotels are included, which vehicle is used, whether fuel and highway tolls are included, how driver accommodation is handled, and which entrance fees are excluded.</p><h2>How to control cost</h2><p>Reduce one-night stops, avoid unnecessary distance, choose the right hotel tier, and decide which paid attractions matter most. A better route can save money without reducing the experience.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Private Tour Costs','Understand Sri Lanka private tour costs including hotels, vehicle, safari fees, guides, season, route length, and chauffeur inclusions.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-10-21 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='experiences' LIMIT 1),'Sri Lanka Food Experiences: Markets, Cooking, Tea, and Seafood','sri-lanka-food-experiences','How to add food experiences to a private Sri Lanka itinerary without making the route feel staged.','<p>Food can turn a Sri Lanka itinerary from a sightseeing route into a real journey. The best food experiences are placed naturally into the day.</p><h2>Where food works best</h2><p>Colombo is strong for street food and markets. Galle is good for cafes and seafood. Kandy and Matale can connect spices and local meals. Tea country adds factory visits and tastings.</p><h2>How to plan it</h2><p>Do not add food as a random evening after a long drive. Use it where the route already pauses. Ask about spice tolerance, dietary needs, and whether travelers prefer home-style meals, street food, or polished dining.</p><h2>Private route value</h2><p>A private driver can time market stops, local lunches, tea tastings, and seafood dinners around the rest of the itinerary without making the day feel forced.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Food Experiences','Plan Sri Lanka food experiences including markets, cooking, tea, seafood, street food, and private itinerary timing.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-10-28 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='itineraries' LIMIT 1),'Sri Lanka Birding and Nature Routes for Repeat Visitors','sri-lanka-birding-nature-routes','A specialist route guide for travelers interested in Sinharaja, Bundala, Mannar, Kumana, Horton Plains, and rainforest habitats.','<p>Repeat visitors often want Sri Lanka beyond the classic route. Birding and nature itineraries need a different design from standard tours.</p><h2>Best nature anchors</h2><p>Sinharaja adds rainforest. Bundala adds wetlands and birdlife. Mannar can suit remote birding and coastal landscapes. Horton Plains adds highland habitat. Kumana can work for south-east nature routes.</p><h2>Planning priorities</h2><p>Use early starts, specialist guides, and weather buffers. Do not pack too many habitats into too few days. Nature routes need patience and flexible timing.</p><h2>Who this suits</h2><p>This is best for birders, photographers, repeat visitors, and travelers who would rather spend a morning in one habitat than rush through three famous sites.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Sri Lanka Birding and Nature Routes','Plan Sri Lanka birding and nature routes with Sinharaja, Bundala, Mannar, Kumana, Horton Plains, private guides, and realistic timing.',NULL,'{"version":2,"widgets":[]}',0,1,'2026-11-04 09:00:00'),
((SELECT id FROM blog_categories WHERE slug='source-markets' LIMIT 1),'Top 20 Countries Visiting Sri Lanka in 2026 and What to Build for Them','top-20-countries-visiting-sri-lanka-2026','How the SLTDA Jan-May 2026 source-market list shapes country pages, itineraries, and private-tour content.','<p>Country-focused pages should not be guessed. For this site, the first source-market set is based on SLTDA Jan-May 2026 arrivals data.</p><h2>Top-market content focus</h2><p>The top 20 markets include India, United Kingdom, Russian Federation, China, Germany, France, Australia, United States, Poland, Netherlands, Canada, Bangladesh, Japan, Italy, Maldives, Switzerland, Malaysia, Spain, Israel, and Denmark.</p><h2>Why this matters</h2><p>Each market searches differently. UK, German, French, US, Australian, Swiss, Dutch, Danish, Italian, Spanish, and Polish travelers often need long-haul pacing and seasonal beach guidance. Regional markets such as India, Bangladesh, Maldives, Malaysia, China, and Japan often need more flight, family, food, heritage, and short-break detail.</p><h2>How to use the country data</h2><p>Country pages should answer direct planning questions in visible text, link to relevant itineraries and destinations, and use structured data that matches the page content.</p>',NULL,NULL,'Island Culture Travels Editorial Team','Top 20 Countries Visiting Sri Lanka in 2026','Use SLTDA Jan-May 2026 source-market data to plan Sri Lanka country pages, itineraries, internal links, and country-specific content.',NULL,'{"version":2,"widgets":[]}',1,1,'2026-11-11 09:00:00')
ON DUPLICATE KEY UPDATE
    updated_at = updated_at;

-- Core interlinks for destination, itinerary, and experience discovery.
INSERT INTO itinerary_destination (itinerary_id, destination_id)
SELECT i.id, d.id FROM itineraries i JOIN destinations d
WHERE i.slug = 'sri-lanka-itinerary-10-days'
  AND d.slug IN ('negombo','sigiriya','kandy','nuwara-eliya','ella','yala','udawalawe','galle','mirissa')
ON DUPLICATE KEY UPDATE itinerary_id = itinerary_id;

INSERT INTO itinerary_destination (itinerary_id, destination_id)
SELECT i.id, d.id FROM itineraries i JOIN destinations d
WHERE i.slug = 'sri-lanka-itinerary-14-days'
  AND d.slug IN ('negombo','sigiriya','anuradhapura','polonnaruwa','kandy','nuwara-eliya','ella','yala','udawalawe','galle','tangalle','bentota')
ON DUPLICATE KEY UPDATE itinerary_id = itinerary_id;

