INSERT INTO experience_itinerary (experience_id, itinerary_id)
SELECT e.id, i.id FROM experiences e JOIN itineraries i
WHERE e.slug IN ('sigiriya-pidurangala-sunrise','kandy-to-ella-train','yala-leopard-safari','udawalawe-elephant-safari','galle-fort-southern-coast','honeymoon-beach-boutique-stays','family-wildlife-beach-route','luxury-slow-travel-sri-lanka')
  AND i.slug IN ('sri-lanka-itinerary-10-days','sri-lanka-itinerary-14-days','sri-lanka-honeymoon-itinerary-12-days','sri-lanka-family-itinerary-10-days','sri-lanka-luxury-itinerary-11-days')
ON DUPLICATE KEY UPDATE experience_id = experience_id;

INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 1, 1, 'Arrival and easy recovery', 'Airport pickup, settle near Negombo or Colombo, light coastal or city time depending on arrival.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 2, 3, 'Cultural Triangle base', 'Drive to Sigiriya, visit Dambulla or village experiences, climb Sigiriya/Pidurangala, and add Minneriya or Kaudulla safari if season suits.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 4, 4, 'Kandy culture', 'Transfer to Kandy with temple, lake, gardens, or cultural performance depending on timing.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 5, 6, 'Tea country and Ella', 'Use a train segment or private scenic drive through tea country, waterfalls, Nine Arch Bridge, and Ella viewpoints.', 'Nuwara Eliya or Ella', 'Kandy to Nuwara Eliya 2.5-3.5 hours; onward to Ella 2-3 hours' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 7, 8, 'Safari and south coast', 'Continue to Yala or Udawalawe for safari, then move toward Galle, Mirissa, or Tangalle for coast time.', 'Yala, Udawalawe, or south coast', 'Ella to safari base 2.5-3.5 hours' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
INSERT INTO itinerary_days (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT i.id, 9, 10, 'Galle, beach, and departure', 'Walk Galle Fort, relax on the beach, then return by expressway for Colombo, Negombo, or airport departure.', 'Galle, Bentota, or Colombo', 'Galle to airport 2-3 hours by expressway' FROM itineraries i WHERE i.slug='sri-lanka-itinerary-10-days'
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), overnight_location=VALUES(overnight_location), travel_time=VALUES(travel_time);
